interface.definition:
a!localVariables(
  local!showRotational: or(
    a!isNullOrEmpty(ri!typeFilter),
    ri!typeFilter = "Rotational"
  ),
  local!showCore: or(
    a!isNullOrEmpty(ri!typeFilter),
    ri!typeFilter = "Core"
  ), 
  local!filteredInternationalConfirmed: count(ri!internationalConfirmed)

  ,
  local!filteredInternationalInProcess: count(ri!internationalInProcess)

  ,
  local!filteredExternalConfirmed: ri!externalNominationsConfirmed

  ,
  local!filteredExternalInProcess: ri!externalNominationsInProcess

  ,
  local!externalOtherRotationalsConfirmed: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648284",
      tointeger(index(local!filteredExternalConfirmed,"subPositionTypeId",{}))
    )
  ),
  local!externalOtherRotationalsInProcess: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648284",
      tointeger(index(local!filteredExternalInProcess,"subPositionTypeId",{}))
    )
  ),
  local!externalTransitionalCoresConfirmed: count(
    wherecontains(
      #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
      tointeger(index(local!filteredExternalConfirmed,"subPositionTypeId",{}))
    )
  ),
  local!externalTransitionalCoresInProcess: count(
    wherecontains(
      #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
      tointeger(index(local!filteredExternalInProcess,"subPositionTypeId",{}))
    )
  ),
  local!externalOtherCoresConfirmed: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648367",
      tointeger(index(local!filteredExternalConfirmed,"subPositionTypeId",{}))
    )
  ),
  local!externalOtherCoresInProcess: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648367",
      tointeger(index(local!filteredExternalInProcess,"subPositionTypeId",{}))
    )
  ),
  local!filteredInternalConfirmed: ri!internalNominationsConfirmed

  ,
  local!filteredInternalInProcess: ri!internalNominationsInProcess

  ,
  local!internalOtherRotationalsConfirmed: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648284",
      tointeger(index(local!filteredinternalConfirmed,"subPositionTypeId",{}))
    )
  ),
  local!internalOtherRotationalsInProcess: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648284",
      tointeger(index(local!filteredInternalInProcess,"subPositionTypeId",{}))
    )
  ),
  local!internalTransitionalCoresConfirmed: count(
    wherecontains(
      #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
      tointeger(index(local!filteredInternalConfirmed,"subPositionTypeId",{}))
    )
  ),
  local!internalTransitionalCoresInProcess: count(
    wherecontains(
      #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
      tointeger(index(local!filteredInternalInProcess,"subPositionTypeId",{}))
    )
  ),
  local!internalOtherCoresConfirmed: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648367",
      tointeger(index(local!filteredInternalConfirmed,"subPositionTypeId",{}))
    )
  ),
  local!internalOtherCoresInProcess: count(
    wherecontains(
      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6648367",
      tointeger(index(local!filteredInternalInProcess,"subPositionTypeId",{}))
    )
  ),
  local!filteredRotationalAskPlan: sum(index(ri!rotationalAskPlan,"plan",{})),
  local!filteredTraditionalRotationalConfirmed: sum(index(ri!rotationalAskActual,"traditionalComplete",0)),
  local!filteredTraditionalRotationalInProcess: sum(index(ri!rotationalAskActual,"traditionalInProcess",0)),
  local!filteredEarlyCareerRotationalConfirmed: sum(index(ri!rotationalAskActual,"earlyCareerComplete",0)),
  local!filteredEarlyCareerRotationalInProcess: sum(index(ri!rotationalAskActual,"earlyCareerInProcess",0)),
  local!filteredOtherRotationalConfirmed: sum(index(ri!nonAskActual,"otherRotationalComplete",0)),
  local!filteredOtherRotationalInProcess: sum(index(ri!nonAskActual,"otherRotationalInProcess",0)),
  local!filteredTransitionalCoreConfirmed: sum(index(ri!nonAskActual,"transitionalComplete",0)),
  local!filteredTransitionalCoreInProcess: sum(index(ri!nonAskActual,"transitionalInProcess",0)),
  local!filteredOtherCoreConfirmed: sum(index(ri!nonAskActual,"otherCoreComplete",0)),
  local!filteredOtherCoreInProcess: sum(index(ri!nonAskActual,"otherCoreInProcess",0)),
  #"SYSTEM_SYSRULES_cardLayout"(
    contents: #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        /* Label */
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: #"SYSTEM_SYSRULES_cardLayout"(
            contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
              labelPosition: "COLLAPSED",
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: "Total",
                style: "STRONG"
              )
            ),
            showBorder: false
          ),
          width: "NARROW"
        ),
        /*Rotational Ask Columns*/
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: #"SYSTEM_SYSRULES_cardLayout"(
            contents: #"SYSTEM_SYSRULES_columnsLayout"(
              columns: {
                /* Plan */
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(local!filteredRotationalAskPlan),
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  ),
                  width: "EXTRA_NARROW"
                ),
                /*Traditional Rotationals*/
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: #"SYSTEM_SYSRULES_columnsLayout"(
                    columns: {
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(local!filteredTraditionalRotationalConfirmed),
                            style: "STRONG"
                          ),
                          align: "CENTER"
                        )
                      ),
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(local!filteredTraditionalRotationalInProcess),
                            style: "STRONG"
                          ),
                          align: "CENTER"
                        )
                      )
                    },
                    spacing: "NONE"
                  )
                ),
                /*Early Career Rotationals*/
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: #"SYSTEM_SYSRULES_columnsLayout"(
                    columns: {
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(local!filteredEarlyCareerRotationalConfirmed),
                            style: "STRONG"
                          ),
                          align: "CENTER"
                        )
                      ),
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(local!filteredEarlyCareerRotationalInProcess),
                            style: "STRONG"
                          ),
                          align: "CENTER"
                        )
                      )
                    },
                    spacing: "NONE"
                  )
                ),
                /*Variance*/
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6636024"(
                        sum(
                          local!filteredTraditionalRotationalConfirmed,
                          local!filteredTraditionalRotationalInProcess,
                          local!filteredEarlyCareerRotationalConfirmed,
                          local!filteredEarlyCareerRotationalInProcess
                        ) - local!filteredRotationalAskPlan
                      ),
                      color: "NEGATIVE",
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  ),
                  width: "EXTRA_NARROW"
                )
              },
              showDividers: true
            ),
            showBorder: false
          ),
          width: if(
            #"SYSTEM_SYSRULES_isPageWidth"({"DESKTOP_NARROW","DESKTOP"}),
            "MEDIUM",
            "WIDE"
          ),
          showWhen: local!showRotational
        ),
        /*Non-traditional Rotational*/
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: #"SYSTEM_SYSRULES_cardLayout"(
            contents: #"SYSTEM_SYSRULES_columnsLayout"(
              columns: {
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                        sum(
                          local!externalOtherRotationalsConfirmed,
                          local!internalOtherRotationalsConfirmed,
                          local!filteredInternationalConfirmed,
                          local!filteredOtherRotationalConfirmed
                        )
                      ),
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  )
                ),
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                        sum(
                          local!externalOtherRotationalsInProcess,
                          local!internalOtherRotationalsInProcess,
                          local!filteredInternationalInProcess,
                          local!filteredOtherRotationalInProcess
                        )
                      ),
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  )
                )
              },
              spacing: "NONE"
            ),
            showBorder: false
          ),
          width: "NARROW",
          showWhen: local!showRotational
        ),
        /*Transitional Core*/
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: #"SYSTEM_SYSRULES_cardLayout"(
            contents: #"SYSTEM_SYSRULES_columnsLayout"(
              columns: {
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                        sum(
                          local!externalTransitionalCoresConfirmed,
                          local!internalTransitionalCoresConfirmed,
                          local!filteredTransitionalCoreConfirmed
                        )
                      ),
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  )
                ),
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                        sum(
                          local!externalTransitionalCoresInProcess,
                          local!internalTransitionalCoresInProcess,
                          local!filteredTransitionalCoreInProcess
                        )
                      ),
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  )
                )
              },
              spacing: "NONE"
            ),
            showBorder: false
          ),
          width: "NARROW",
          showWhen: local!showCore
        ),
        /*Other Core*/
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: #"SYSTEM_SYSRULES_cardLayout"(
            contents: #"SYSTEM_SYSRULES_columnsLayout"(
              columns: {
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                        sum(
                          local!externalOtherCoresConfirmed,
                          local!internalOtherCoresConfirmed,
                          local!filteredOtherCoreConfirmed
                        )
                      ),
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  )
                ),
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                        sum(
                          local!externalOtherCoresInProcess,
                          local!internalOtherCoresInProcess,
                          local!filteredOtherCoreInProcess
                        )
                      ),
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  )
                )
              },
              spacing: "NONE"
            ),
            showBorder:false
          ),
          width: "NARROW",
          showWhen: local!showCore
        ),
        /*Total*/
        #"SYSTEM_SYSRULES_columnLayout"(
          width: "NARROW",
          contents: #"SYSTEM_SYSRULES_cardLayout"(
            contents: #"SYSTEM_SYSRULES_columnsLayout"(
              columns: {
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                        if(
                          a!isNullOrEmpty(ri!typeFilter),
                          sum(
                            local!filteredTraditionalRotationalConfirmed,
                            local!filteredEarlyCareerRotationalConfirmed,
                            local!filteredInternationalConfirmed,
                            local!externalOtherRotationalsConfirmed,
                            local!externalTransitionalCoresConfirmed,
                            local!externalOtherCoresConfirmed,
                            local!internalOtherRotationalsConfirmed,
                            local!internalTransitionalCoresConfirmed,
                            local!internalOtherCoresConfirmed,
                            local!filteredOtherRotationalConfirmed,
                            local!filteredTransitionalCoreConfirmed,
                            local!filteredOtherCoreConfirmed
                          ),
                          if(
                            ri!typeFilter = "Rotational",
                            sum(
                              local!filteredTraditionalRotationalConfirmed,
                              local!filteredEarlyCareerRotationalConfirmed,
                              local!filteredInternationalConfirmed,
                              local!externalOtherRotationalsConfirmed,
                              local!internalOtherRotationalsConfirmed,
                              local!filteredOtherRotationalConfirmed
                            ),
                            sum(
                              local!externalTransitionalCoresConfirmed,
                              local!externalOtherCoresConfirmed,
                              local!internalTransitionalCoresConfirmed,
                              local!internalOtherCoresConfirmed,
                              local!filteredTransitionalCoreConfirmed,
                              local!filteredOtherCoreConfirmed
                            )
                          )
                        )
                      ),
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  )
                ),
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6635835"(
                        if(
                          a!isNullOrEmpty(ri!typeFilter),
                          sum(
                            local!filteredTraditionalRotationalInProcess,
                            local!filteredEarlyCareerRotationalInProcess,
                            local!filteredInternationalInProcess,
                            local!externalOtherRotationalsInProcess,
                            local!externalTransitionalCoresInProcess,
                            local!externalOtherCoresInProcess,
                            local!internalOtherRotationalsInProcess,
                            local!internalTransitionalCoresInProcess,
                            local!internalOtherCoresInProcess,
                            local!filteredOtherRotationalInProcess,
                            local!filteredTransitionalCoreInProcess,
                            local!filteredOtherCoreInProcess
                          ),
                          if(
                            ri!typeFilter = "Rotational",
                            sum(
                              local!filteredTraditionalRotationalInProcess,
                              local!filteredEarlyCareerRotationalInProcess,
                              local!filteredInternationalInProcess,
                              local!externalOtherRotationalsInProcess,
                              local!internalOtherRotationalsInProcess,
                              local!filteredOtherRotationalInProcess
                            ),
                            sum(
                              local!externalTransitionalCoresInProcess,
                              local!externalOtherCoresInProcess,
                              local!internalTransitionalCoresInProcess,
                              local!internalOtherCoresInProcess,
                              local!filteredTransitionalCoreInProcess,
                              local!filteredOtherCoreInProcess
                            )
                          )
                        )
                      ),
                      style: "STRONG"
                    ),
                    align: "CENTER"
                  )
                )
              },
              spacing: "NONE"
            ),
            showBorder: false
          )
        )
      },
      alignVertical: "BOTTOM",
      spacing: "NONE",
      showDividers: true
    ),
    padding: "NONE",
    showBorder: false
  )
)
